@layer gardener.components {
  .g-btn {
    --g-btn-bg: var(--g-color-surface);
    --g-btn-color: var(--g-color-text);
    --g-btn-border: var(--g-color-border-strong);
    display: inline-flex;
    min-height: var(--g-control-height-md);
    align-items: center;
    justify-content: center;
    gap: var(--g-space-2);
    padding: var(--g-space-control-y) var(--g-space-control-x);
    border: var(--g-border-width) solid var(--g-btn-border);
    border-radius: var(--g-radius-md);
    background: var(--g-btn-bg);
    color: var(--g-btn-color);
    font-weight: 600;
    line-height: 1.2;
    text-decoration: none;
    cursor: pointer;
    transition: background var(--g-duration-fast), border-color var(--g-duration-fast), color var(--g-duration-fast), box-shadow var(--g-duration-fast), transform var(--g-duration-fast);
  }
  .g-btn:hover:not(:disabled, [aria-disabled="true"]) { filter: brightness(0.97); }
  .g-btn:active:not(:disabled, [aria-disabled="true"]) { transform: translateY(1px); }
  .g-btn:disabled, .g-btn[aria-disabled="true"] { opacity: 0.55; pointer-events: none; }
  .g-btn-primary { --g-btn-bg: var(--g-color-primary); --g-btn-border: var(--g-color-primary); --g-btn-color: var(--g-color-on-primary); }
  .g-btn-primary:hover:not(:disabled) { --g-btn-bg: var(--g-color-primary-hover); --g-btn-border: var(--g-color-primary-hover); }
  .g-btn-outline { --g-btn-bg: transparent; --g-btn-border: var(--g-color-primary-text); --g-btn-color: var(--g-color-primary-text); }
  .g-btn-ghost { --g-btn-bg: transparent; --g-btn-border: transparent; }
  .g-btn-danger { --g-btn-bg: var(--g-color-danger); --g-btn-border: var(--g-color-danger); --g-btn-color: #fff; }
  .g-btn-link { --g-btn-bg: transparent; --g-btn-border: transparent; --g-btn-color: var(--g-color-primary-text); padding-inline: 0; }
  .g-btn-sm { min-height: var(--g-control-height-sm); padding: var(--g-space-1) var(--g-space-3); font-size: var(--g-font-size-sm); }
  .g-btn-lg { min-height: var(--g-control-height-lg); padding-inline: var(--g-space-5); font-size: var(--g-font-size-lg); }
  .g-btn-icon { inline-size: var(--g-control-height-md); padding: 0; }
