  .g-auth-card { width: min(100%, 28rem); display: grid; gap: var(--g-space-5); padding: clamp(1.25rem, 4vw, 2rem); background: var(--g-color-surface); border: var(--g-border-width) solid var(--g-color-border); border-radius: var(--g-radius-lg); box-shadow: var(--g-shadow-sm); }
